  check('Maria: aging por faixa (1-30, 31-60, 61-90, 90+)', lm?.aging?.D1_30 > 1000 && lm?.aging?.D31_60 > 1000 && lm?.aging?.D61_90 > 1000 && lm?.aging?.D90_MAIS > 1000 && lm?.aging?.A_VENCER === 800, lm?.aging)
