  check('CSV: nome iniciado por "=" é neutralizado (sem injeção de fórmula)', r.text.includes("'=cmd|calc") && !/(^|;)=cmd/m.test(r.text))
  check('CSV: usa vírgula decimal', /\d+,\d{1,2};/.test(r.text))
