  check('detalhe: título tem multa/juros/faixa por título', r.json.titulos.filter((t: any) => t.diasAtraso > 0).every((t: any) => t.multa > 0 && t.juros > 0 && t.faixa !== 'A_VENCER'))
  check('B não vê o aluno de A (404)', (await call(finB, 'GET', `/edu/cobranca/inadimplentes/${sid}`)).status === 404)
