  check('calcular com quitação: desconto 50% dos encargos + 10% do principal, bolsa não bloqueia', r.status === 200 && near(r.json.desconto.descontoEncargos, round2(encPedro * 0.5), 0.02) && r.json.desconto.descontoPrincipal === 100 && r.json.totalAPagar < r.json.saldo, r.json.desconto)
