  const rec1 = r.json?.recebimento
  check('parcial: encargos pagos primeiro (R$ ' + encPedro.toFixed(2) + ') depois principal', near(rec1?.encargos, encPedro, 0.02) && near(rec1?.principal, 300 - encPedro, 0.02) && !!rec1?.transacaoId, rec1)
