  const lanc1 = await prisma.accountingEntry.findFirst({ where: { paymentTransactionId: trans1?.id } })
  check('parcial gera PaymentTransaction e lançamento contábil de 300', trans1?.valor === 300 && trans1?.accountReceivableId === arP.id && lanc1?.valor === 300)
  r = await call(fin, 'GET', `/edu/cobranca/inadimplentes/${pedro.id}`)
