  const recL = r.json?.recebimento
  const alocL = await prisma.cobAlocacao.findFirst({ where: { receivableId: arL.id } })
  check('quitação registra o desconto como abatimento (principal e encargos)', alocL?.descontoPrincipal === 200 && (alocL?.descontoEncargos ?? 0) > 0 && recL?.desconto === round2((alocL?.descontoPrincipal ?? 0) + (alocL?.descontoEncargos ?? 0)), alocL)
  const bia = await mkAluno('Bia Bolsista')
  await prisma.apoConcessaoBolsa.create({ data: { tenantId: A, programaId: 'p', studentId: bia.id, percentual: 30, inicio: new Date(Date.now() - 30 * DIA), fim: new Date(Date.now() + 300 * DIA), status: 'ATIVA' } as any })
  const arBia = await mkAR(bia.id, 40, 2000, 'Mensalidade', 1)
