  check('bolsista: desconto de quitação NÃO incide sobre o principal (política)', r.status === 200 && r.json.temBolsa && r.json.descontoBloqueadoPorBolsa && r.json.desconto.descontoPrincipal === 0 && r.json.desconto.descontoEncargos > 0, r.json.desconto)
  r = await call(fin, 'POST', '/edu/cobranca/pagamentos', { receivableId: arBia.id, valor: 100, forma: 'PIX', quitacao: true })
  check('quitação exige pagamento integral (422)', r.status === 422, r.json)
  // baixa pelo financeiro (rota existente) deve fechar o caso/promessa do aluno
