  check('promessa registrada (caso passa a PROMESSA)', r.status === 201 && (await prisma.cobCaso.findFirst({ where: { tenantId: A, studentId: rafa.id } }))?.status === 'PROMESSA', r.json)
  r = await call(fin, 'POST', `/edu/financeiro/receivables/${arR.id}/receive`, { formaPagamento: 'PIX' })
  check('rota do financeiro baixa o título', r.status === 200 && r.json.receivable.status === 'PAGO', r.json)
