  r = await call(fin, 'GET', `/edu/cobranca/recebimentos?de=${new Date(Date.now() - DIA).toISOString().slice(0, 10)}&ate=${new Date(Date.now() + DIA).toISOString().slice(0, 10)}`)
  check('recebimentos do período: totais, recuperado em atraso, por forma e por dia', r.status === 200 && r.json.totais.titulosPagos >= 4 && r.json.totais.recuperadoEmAtraso > 0 && r.json.totais.caixaTotal > 0 && Object.keys(r.json.totais.porForma).length >= 2 && r.json.porDia.length >= 1 && r.json.recebimentos.length >= 4, r.json?.totais)
  check('recebimentos: descontos concedidos somados', r.json?.totais?.descontosConcedidos > 200)
