  const arG = await mkAR(gil.id, 12, 500, 'Mensalidade', 1)
  r = await call(fin, 'POST', '/edu/cobranca/promessas', { studentId: gil.id, valor: 500, dataPrometida: new Date(Date.now() - 2 * DIA).toISOString() })
  check('promessa no passado = 422', r.status === 422, r.json)
