  const prom1 = r.json
  check('promessa válida criada ABERTA', r.status === 201 && prom1.status === 'ABERTA')
  r = await call(fin, 'POST', '/edu/cobranca/promessas', { studentId: gil.id, valor: 250, dataPrometida: new Date(Date.now() + 6 * DIA).toISOString() })
