  const promG = r.json
  r = await call(fin, 'GET', `/edu/cobranca/promessas?studentId=${gil.id}`)
  check('lista promessas com nome do aluno', r.json.items.length === 2 && r.json.items[0].aluno === 'Gil Promessa')
  check('B não vê promessas de A', (await call(finB, 'GET', '/edu/cobranca/promessas')).json?.items?.length === 0 && (await call(finB, 'POST', `/edu/cobranca/promessas/${promG.id}/cumprir`)).status === 404)
  const jp = await jobPromessas({ tenantId: A, now: new Date(Date.now() + 3 * DIA) })
  check('job: promessa ainda no prazo não é quebrada', jp.quebradas === 0)
  const jp2 = await jobPromessas({ tenantId: A, now: new Date(Date.now() + 8 * DIA) })
