  check('dry-run: mensagem renderizada com saldo e dias', /R\$\s?1\.0\d\d,\d\d/.test(sr?.mensagem) && /\(6 dias\)|\(7 dias\)/.test(sr?.mensagem) && sr.mensagem.startsWith('Olá Rita'), sr?.mensagem)
  const m1 = await motor(t0)
  const cRita = () => prisma.cobContato.findMany({ where: { studentId: rita.id, tipo: { not: 'NOTA' } }, orderBy: { createdAt: 'asc' } })
  let cr = await cRita()
  check('1ª execução: UMA mensagem (E2/SMS), não rajada com E1', cr.length === 1 && cr[0].canal === 'SMS' && cr[0].automatico && cr[0].resultado === 'ENFILEIRADO' && cr[0].baseLegal === 'EXECUCAO_CONTRATO' && cr[0].finalidade === 'COBRANCA', cr)
  const exs = await prisma.cobExecucao.findMany({ where: { tenantId: A }, include: undefined })
  const exMap = new Map(exs.map((x) => [x.etapaId, x]))
  const [e1, e2, e3] = regua.etapas.sort((a: any, b: any) => a.diaAtraso - b.diaAtraso)
  check('etapa anterior (E1) marcada SUPERADA e E2 com 1 ocorrência', exMap.get(e1.id)?.resultado === 'SUPERADA' && exMap.get(e2.id)?.ocorrencias === 1)
  const nt = await prisma.eduNotification.findFirst({ where: { refType: 'CobContato', refId: cr[0].id } })
  check('reaproveita a caixa de saída: EduNotification SMS com refType CobContato', nt?.canal === 'SMS' && nt.studentId === rita.id && nt.status === 'PENDENTE' && nt.mensagem.includes('Rita') && cr[0].notificationId === nt.id, nt)
  check('destino mascarado no histórico (LGPD)', /^\*\*\*\d{4}$/.test(cr[0].destino ?? ''), cr[0].destino)
  check('resumo do motor: 1 contato, casos avaliados', m1.contatos >= 1 && m1.casosAvaliados >= 1 && m1.pulados.PAUSADO >= 1)
  const mDup = await motor(t0)
  check('2ª execução no mesmo instante não duplica', (await cRita()).length === 1 && mDup.contatos === 0)
  await motor(new Date(t0.getTime() + 1 * DIA))
  check('antes do intervalo (3 dias) não repete', (await cRita()).length === 1)
  await motor(new Date(t0.getTime() + 3 * DIA))
  cr = await cRita()
  check('recorrência: repete E2 após 3 dias', cr.length === 2 && cr[1].canal === 'SMS' && cr[1].etapaId === e2.id)
  await motor(new Date(t0.getTime() + 6 * DIA))
  cr = await cRita()
  check('atraso 12: entra E3 (e-mail) e E2 para de repetir', cr.length === 3 && cr[2].canal === 'EMAIL' && cr[2].etapaId === e3.id && cr[2].assunto === 'Pendência financeira', cr.map((c) => c.canal))
  await motor(new Date(t0.getTime() + 8 * DIA))
  check('E3 não repete antes de 5 dias; E2 não volta', (await cRita()).length === 3)
  await motor(new Date(t0.getTime() + 11 * DIA))
  cr = await cRita()
  check('E3 continua repetindo (a cada 5 dias) até a resolução', cr.length === 4 && cr[3].canal === 'EMAIL')
  const exE3 = await prisma.cobExecucao.findFirst({ where: { etapaId: e3.id } })
  check('execução da recorrência guarda ocorrências e última data', exE3?.ocorrencias === 2 && exE3.ultimaEm!.getTime() === new Date(t0.getTime() + 11 * DIA).getTime())
  // escalonamento: atraso 6 + 16 = 22 -> E4 (extrajudicial); E5 (25) ainda não
  const m16 = await motor(new Date(t0.getTime() + 16 * DIA))
  let encs = await prisma.cobEncaminhamento.findMany({ where: { studentId: rita.id }, orderBy: { createdAt: 'asc' } })
  check('atraso 22: gera NOTIFICAÇÃO EXTRAJUDICIAL (com documento) e cópia por e-mail', encs.length === 1 && encs[0].tipo === 'NOTIFICACAO_EXTRAJUDICIAL' && !!encs[0].documentoHtml && encs[0].documentoHtml.includes('NOTIFICAÇÃO EXTRAJUDICIAL') && /^ENC-\d{4}-\d{5}$/.test(encs[0].numero) && m16.escalonamentos === 1, encs)
  check('notificação extrajudicial: e-mail enfileirado com texto formal (protesto permitido só nela)', ['ENVIADO', 'GERADO'].includes(encs[0].status) && (await prisma.cobContato.count({ where: { studentId: rita.id, canal: 'EMAIL', assunto: { contains: 'Notificação extrajudicial' } } })) <= 1)
  await motor(new Date(t0.getTime() + 19 * DIA))
  const encEx = await prisma.cobEncaminhamento.findUnique({ where: { id: encs[0].id } })
