  const m20 = await motor(new Date(t0.getTime() + 20 * DIA)) // atraso 26: negativação, mas aviso prévio (10 dias) não cumprido
  encs = await prisma.cobEncaminhamento.findMany({ where: { studentId: rita.id }, orderBy: { createdAt: 'asc' } })
  check('negativação bloqueada: falta o aviso prévio de 10 dias após a notificação', encs.length === 1 && m20.escalonamentosBloqueados >= 1, encs.map((x) => x.tipo))
  const ex5 = await prisma.cobExecucao.findMany({ where: { etapaId: regua.etapas.find((x: any) => x.acao === 'NEGATIVACAO').id } })
  check('etapa bloqueada fica AGUARDANDO_PRE_REQUISITO (será reavaliada)', ex5[0]?.resultado === 'AGUARDANDO_PRE_REQUISITO' && !ex5[0].encerrada)
  await motor(new Date(t0.getTime() + 27 * DIA))
  check('ainda bloqueada aos 7 dias do aviso (10 exigidos)', (await prisma.cobEncaminhamento.count({ where: { studentId: rita.id, tipo: 'NEGATIVACAO' } })) === 0)
  const m27 = await motor(new Date(t0.getTime() + 31 * DIA)) // atraso 37: aviso há 11 dias -> negativação e protesto (aguardam aprovação)
  encs = await prisma.cobEncaminhamento.findMany({ where: { studentId: rita.id }, orderBy: { createdAt: 'asc' } })
  const neg = encs.find((x) => x.tipo === 'NEGATIVACAO'), prot = encs.find((x) => x.tipo === 'PROTESTO')
  check('cumprido o aviso prévio: negativação e protesto SIMULADOS aguardam aprovação humana', !!neg && !!prot && neg.status === 'AGUARDANDO_APROVACAO' && neg.simulado && prot.simulado && m27.escalonamentos >= 2, encs.map((x) => `${x.tipo}:${x.status}`))
  r = await call(fin, 'POST', `/edu/cobranca/encaminhamentos/${neg!.id}/aprovar`, {})
  check('aprovar negativação: ENVIADO com protocolo SIMULADO (sem bureau real)', r.status === 200 && r.json.status === 'ENVIADO' && r.json.protocoloExterno.startsWith('SIMULADO-') && r.json.simulado === true, r.json)
  check('aprovar de novo = 409', (await call(fin, 'POST', `/edu/cobranca/encaminhamentos/${neg!.id}/aprovar`, {})).status === 409)
  r = await call(fin, 'POST', `/edu/cobranca/encaminhamentos/${prot!.id}/cancelar`, { motivo: 'Aluno procurou o financeiro' })
  check('cancelar protesto antes do envio', r.status === 200 && r.json.status === 'CANCELADO')
  check('encaminhamento de B inacessível', (await call(finB, 'POST', `/edu/cobranca/encaminhamentos/${neg!.id}/aprovar`, {})).status === 404 && (await call(finB, 'GET', `/edu/cobranca/encaminhamentos/${neg!.id}`)).status === 404)
  // jurídico: atraso >= 40 (t0+36)
  const entregues: any[] = []
  registrarHandlerJuridico(async (s) => { entregues.push(s) })
  await motor(new Date(t0.getTime() + 36 * DIA))
  encs = await prisma.cobEncaminhamento.findMany({ where: { studentId: rita.id, tipo: 'JURIDICO' } })
  check('atraso 42: solicitação de execução ao Jurídico aguardando aprovação', encs.length === 1 && encs[0].status === 'AGUARDANDO_APROVACAO')
  const jx0 = encs[0]
  const pay = jx0.payload as any
  check('contrato SolicitacaoExecucaoV1: versão, origem, devedor, débito com títulos e histórico', pay.versao === 'cobranca.solicitacao-execucao.v1' && pay.origem.casoId && pay.origem.encaminhamentoId === jx0.id && pay.devedor.nome === 'Rita Recorrência' && pay.debito.titulos.length === 1 && pay.debito.titulos[0].receivableId === tR.id && pay.debito.valorTotal > 1000 && pay.historico.totalContatos >= 4 && pay.historico.notificacaoExtrajudicial?.numero && pay.baseLegal === 'EXERCICIO_REGULAR_DIREITOS', pay)
  check('payload: débito soma principal + encargos e traz a política usada', near(pay.debito.valorTotal, pay.debito.valorPrincipal + pay.debito.encargos, 0.02) && pay.debito.politica.multaPct === 2)
  check('ninguém é entregue ao Jurídico antes da aprovação', entregues.length === 0)
  r = await call(fin, 'POST', `/edu/cobranca/encaminhamentos/${jx0.id}/aprovar`, {})
  check('aprovado: ENVIADO, caso JURIDICO e handler do Jurídico recebe o payload', r.status === 200 && r.json.status === 'ENVIADO' && entregues.length === 1 && entregues[0].numero === jx0.numero && (await prisma.cobCaso.findFirst({ where: { studentId: rita.id } }))?.status === 'JURIDICO')
  registrarHandlerJuridico(null)
  r = await call(jur, 'GET', '/edu/cobranca/juridico/solicitacoes')
  check('papel sem relação com o jurídico não acessa o contrato (403)', r.status === 403)
  r = await call(fin, 'GET', '/edu/cobranca/juridico/solicitacoes?status=ENVIADO')
  check('endpoint do Jurídico lista as solicitações enviadas', r.status === 200 && r.json.items.length === 1 && r.json.items[0].id === jx0.id)
  check('contrato documentado em /juridico/contrato', (await call(fin, 'GET', '/edu/cobranca/juridico/contrato')).json?.versao === 'cobranca.solicitacao-execucao.v1')
  r = await call(fin, 'POST', `/edu/cobranca/juridico/solicitacoes/${jx0.id}/retorno`, { status: 'DEVOLVIDO' })
  check('devolução exige motivo (400)', r.status === 400)
  r = await call(fin, 'POST', `/edu/cobranca/juridico/solicitacoes/${jx0.id}/retorno`, { status: 'CONCLUIDO' })
  check('transição inválida (ENVIADO -> CONCLUIDO) = 409', r.status === 409)
  r = await call(fin, 'POST', `/edu/cobranca/juridico/solicitacoes/${jx0.id}/retorno`, { status: 'ACEITO', protocolo: '0001234-56.2026.8.26.0100' })
  check('retorno do Jurídico: ACEITO com nº do processo', r.status === 200 && r.json.status === 'ACEITO' && r.json.protocoloExterno === '0001234-56.2026.8.26.0100')
  check('motor não cobra quem está no jurídico', ((await motor(new Date(t0.getTime() + 40 * DIA))).pulados.JURIDICO ?? 0) >= 1)
  // pagamento total encerra tudo
