  const negFim = await prisma.cobEncaminhamento.findUnique({ where: { id: neg!.id } })
  check('negativação enviada ganha aviso "solicitar baixa" após a quitação', /QUITADO/.test(negFim?.retornoMotivo ?? ''), negFim?.retornoMotivo)
  const antes = (await cRita()).length
  await motor(new Date(t0.getTime() + 60 * DIA))
  check('pausa automática por pagamento: a régua para de cobrar', (await cRita()).length === antes)

  // ---- pausa por acordo e por promessa
  secao('Pausa automática (acordo, promessa, pausa manual) e escalonamento sem pré-requisito')
