  r = await call(fin, 'POST', `/edu/cobranca/casos/${casoSara!.id}/pausar`, { ate: new Date(tS.getTime() + 10 * DIA).toISOString(), motivo: 'aluno em tratamento de saúde' })
  const mPz = await motor(tS)
