  check('pausa acima de 90 dias é recusada', (await call(fin, 'POST', `/edu/cobranca/casos/${casoSara!.id}/pausar`, { ate: new Date(tS.getTime() + 200 * DIA).toISOString(), motivo: 'longa demais' })).status === 422)
  check('retomar caso', (await call(fin, 'POST', `/edu/cobranca/casos/${casoSara!.id}/retomar`, {})).json?.pausadoAte === null)
  const mR = await motor(tS)
  check('retomada: a régua volta a cobrar (E1 WhatsApp, atraso 8 => E2 SMS por ser a maior)', (await prisma.cobContato.count({ where: { studentId: sara.id, automatico: true, resultado: 'ENFILEIRADO' } })) === 1 && mR.contatos >= 1)
  // acordo pausa
