  check('opt-out respeitado: BLOQUEADO_OPTOUT registrado, nada enviado', t.resultado === 'BLOQUEADO_OPTOUT' && (await prisma.eduNotification.count({ where: { studentId: zeca.id, canal: 'WHATSAPP' } })) === 1)
  t = await tentarContato({ ...base1, canal: 'WHATSAPP', canalFallback: 'TELEGRAM', now: new Date(Date.now() + 6 * DIA) })
