  t = await tentarContato({ ...base1, canal: 'EMAIL', canalFallback: 'SMS', now: new Date(Date.now() + 9 * DIA) })
  check('opt-out geral (*) bloqueia todos os canais, inclusive o alternativo', t.resultado === 'BLOQUEADO_OPTOUT')
  check('histórico guarda o opt-out e os bloqueios', (await prisma.cobContato.count({ where: { studentId: zeca.id, observacao: { contains: 'OPT-OUT' } } })) === 2 && (await prisma.cobContato.count({ where: { studentId: zeca.id, resultado: 'BLOQUEADO_OPTOUT' } })) >= 2)
  const mO = await motor(new Date(Date.now() + 12 * DIA))
  check('motor automático também respeita o opt-out geral', (await prisma.cobContato.count({ where: { studentId: zeca.id, automatico: true, resultado: 'ENFILEIRADO' } })) === 0 && (mO.bloqueados.BLOQUEADO_OPTOUT ?? 0) >= 1, mO.bloqueados)
  r = await call(fin, 'POST', `/edu/cobranca/casos/${casoZ!.id}/optin`, { canal: '*' })
  t = await tentarContato({ ...base1, canal: 'EMAIL', now: new Date(Date.now() + 20 * DIA) })
  check('opt-in restabelece o contato', r.status === 200 && t.resultado === 'ENFILEIRADO')
  // não contatar
